import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:oil_gas_tycoon/src/save_store.dart';
import 'package:oil_gas_tycoon/src/tycoon_engine.dart';

import 'app_host_test.dart' show displayedGame, mountHost;
import 'save_store_test.dart' show MemorySaveStorage;

// Generated by the unmodified 16ae7a7 version 1 engine, after real successful
// production, trading, hiring, lease development, and contract actions.
String legacyBackup() =>
    File('test/fixtures/legacy_v1_company.json').readAsStringSync();

void main() {
  test('a shipped version 1 company keeps every existing field on migration',
      () {
    final source = legacyBackup();
    final previous =
        (jsonDecode(source) as Map<String, dynamic>)['game'] as Map;
    final migrated = TycoonSaveStore.decode(source);
    final current = migrated.toJson();

    for (final entry in previous.entries) {
      if (entry.key == 'schemaVersion') continue;
      expect(current[entry.key], entry.value,
          reason: 'Migration must preserve the old ${entry.key} field.');
    }
    expect(current['schemaVersion'], GameState.schemaVersion);
    expect(migrated.companyName, 'Legacy North Star');
    expect(migrated.day, 3);
    expect(migrated.cash, 31915);
    expect(migrated.oilInventory, 242);
    expect(migrated.researchProject, isNull);
    expect(migrated.researchLevels.values.every((level) => level == 0), isTrue);
    expect(migrated.auctions.where((lot) => lot.status == AuctionStatus.open),
        hasLength(3));
    expect(TycoonSaveStore.decode(TycoonSaveStore.encode(migrated)).toJson(),
        current);
  });

  test('first upgraded save retains the untouched legacy backup for recovery',
      () async {
    final old = legacyBackup();
    final storage = MemorySaveStorage()
      ..values[TycoonSaveStore.primaryKey] = old;
    final store = TycoonSaveStore(storage);
    final loaded = await store.load();
    expect(loaded.warning, isNull);
    expect(storage.values[TycoonSaveStore.primaryKey], old);

    final engine = GameEngine(loaded.state!);
    expect(engine.startResearch('maintenance').success, isTrue);
    await store.save(engine.state);
    expect(storage.values[TycoonSaveStore.backupKey], old);
    expect((await TycoonSaveStore(storage).load()).state!.toJson(),
        engine.state.toJson());

    storage.values[TycoonSaveStore.primaryKey] = '{interrupted upgraded save';
    final recovered = await TycoonSaveStore(storage).load();
    expect(recovered.warning, contains('Recovered'));
    expect(recovered.state!.companyName, 'Legacy North Star');
    expect(recovered.state!.cash, 31915);
    expect(recovered.state!.researchProject, isNull);
  });

  test('pending research survives export, restart, and staffed completion',
      () async {
    final storage = MemorySaveStorage()
      ..values[TycoonSaveStore.primaryKey] = legacyBackup();
    final store = TycoonSaveStore(storage);
    final engine = GameEngine((await store.load()).state!);
    expect(engine.startResearch('maintenance').success, isTrue);
    expect(engine.advanceDay().success, isTrue);
    await store.save(engine.state);

    final resumed = GameEngine((await TycoonSaveStore(storage).load()).state!);
    expect(resumed.state.toJson(), engine.state.toJson());
    expect(resumed.state.researchProject!.remainingShifts, 1);
    final transferred = GameEngine(
        TycoonSaveStore.decode(TycoonSaveStore.encode(resumed.state)));
    expect(transferred.advanceDay().success, isTrue);
    expect(transferred.researchLevel('maintenance'), 1);
    expect(transferred.state.researchProject, isNull);
    expect(
        TycoonSaveStore.decode(TycoonSaveStore.encode(transferred.state))
            .toJson(),
        transferred.state.toJson());
  });

  testWidgets(
      'the mobile host resumes a legacy company and saves its next shift',
      (tester) async {
    final storage = MemorySaveStorage()
      ..values[TycoonSaveStore.primaryKey] = legacyBackup();
    final store = TycoonSaveStore(storage);
    await mountHost(tester, store, size: const Size(390, 844));
    expect(find.text('Legacy North Star'), findsOneWidget);
    expect(displayedGame(tester).state.cash, 31915);
    expect(displayedGame(tester).state.leases, hasLength(2));
    expect(find.text('Your company starts here'), findsNothing);

    await tester.tap(find.byKey(const Key('advance-shift')));
    await tester.pumpAndSettle();
    await store.flush();
    final played = displayedGame(tester).state.toJson();
    expect(played['day'], 4);
    await tester.pumpWidget(const SizedBox.shrink());
    await tester.pumpAndSettle();
    await mountHost(tester, TycoonSaveStore(storage),
        size: const Size(390, 844));
    expect(displayedGame(tester).state.toJson(), played);
    expect(tester.takeException(), isNull);
  });
}
